/** Source: intro.c → SpriteCB_PlayerOnBicycle */
export const SpriteCB_PlayerOnBicycle: SpriteCallback = (sprite, rt) => {
  switch (sprite.data[0])
      {
      case 0:
           
          rt.StartSpriteAnim(sprite.spriteId, 0);
          sprite.x--;
          break;
      case 1:
           
          rt.StartSpriteAnim(sprite.spriteId, 0);
          if (rt.gIntroFrameCounter & 7)
              return;
          sprite.x++;
          break;
      case 2:
           
          if (sprite.x <= 120 || rt.gIntroFrameCounter & 7)
              sprite.x++;
          break;
      case 3:
           
          break;
      case 4:
           
          if (sprite.x > -32)
              sprite.x -= 2;
          break;
      }

      if (rt.gIntroFrameCounter & 7)
          return;

       
      if (sprite.y2 != 0)
      {
           
          sprite.y2 = 0;
      }
      else
      {
           
          switch (Math.floor(Math.random() * 0x10000) & 3)
          {
          case 0:
              sprite.y2 = -1;
              break;
          case 1:
              sprite.y2 = 1;
              break;
          case 2:
          case 3:
              sprite.y2 = 0;
              break;
          }
      }
};

/** Source: intro.c → SpriteCB_Flygon */
export const SpriteCB_Flygon: SpriteCallback = (sprite, rt) => {
  switch (sprite.data[0])
      {
      case 0:
          break;
      case 1:
          if (sprite.x2 + sprite.x < DISPLAY_WIDTH + 64)
              sprite.x2 += 8;
          else
              sprite.data[0] = 2;
          break;
      case 2:
          if (sprite.x2 + sprite.x > 120)
              sprite.x2 -= 1;
          else
              sprite.data[0] = 3;
          break;
      case 3:
          if (sprite.x2 > 0)
              sprite.x2 -= 2;
          break;
      }
      sprite.y2 = Sin(sprite.data[1], 8) - sFlygonYOffset;
      sprite.data[1] += 4;
};

/** Source: intro.c → SpriteCB_LogoLetter */
export const SpriteCB_LogoLetter: SpriteCallback = (sprite, rt) => {
  switch (sprite.data[0])
      {
      case 0:
          if (sprite.data[7] != 0)
          {
              sprite.data[7]--;
          }
          else
          {
               
              sprite.invisible = false;
              rt.StartSpriteAffineAnim(sprite.spriteId, 1);
              sprite.data[0]++;
          }
          break;
      case 1:
          if (rt.gIntroFrameCounter >= TIMER_LOGO_LETTERS_COLOR)
          {
               
              sprite.data[0]++;
              sprite.data[7] = COLOR_CHANGES;
              sprite.data[3] = 2;
          }
          break;
      case 2:
           
          if (sprite.data[3] == 0)
          {
              sprite.data[3] = 2;
              if (sprite.data[7] != 0)
              {
                  rt.CpuCopy16((rt.getExtraPalette("&gIntroGameFreakTextFade_Pal[sprite.data[7]]") ?? new Uint16Array(0)), 0, (256 + (1) * 16) + 15, Math.floor((PLTT_SIZEOF(1) / 2)));
                  rt.CpuCopy16((rt.getExtraPalette("&gIntroGameFreakTextFade_Pal[sprite.data[7] + 16]") ?? new Uint16Array(0)), 0, (256 + (1) * 16) + 4, Math.floor((PLTT_SIZEOF(1) / 2)));
                  rt.CpuCopy16((rt.getExtraPalette("&gIntroGameFreakTextFade_Pal[sprite.data[7] + 32]") ?? new Uint16Array(0)), 0, (256 + (1) * 16) + 10, Math.floor((PLTT_SIZEOF(1) / 2)));
                  sprite.data[7]--;
              }
              else
              {
                  rt.CpuCopy16((rt.getExtraPalette("&gIntroGameFreakTextFade_Pal[sprite.data[7]]") ?? new Uint16Array(0)), 0, (256 + (1) * 16) + 15, Math.floor((PLTT_SIZEOF(1) / 2)));
                  rt.CpuCopy16((rt.getExtraPalette("&gIntroGameFreakTextFade_Pal[sprite.data[7] + 16]") ?? new Uint16Array(0)), 0, (256 + (1) * 16) + 4, Math.floor((PLTT_SIZEOF(1) / 2)));
                  rt.CpuCopy16((rt.getExtraPalette("&gIntroGameFreakTextFade_Pal[sprite.data[7] + 32]") ?? new Uint16Array(0)), 0, (256 + (1) * 16) + 10, Math.floor((PLTT_SIZEOF(1) / 2)));
                  sprite.data[0]++;
              }
          }
          else
          {
              sprite.data[3]--;
          }
          break;
      case 3:
           
          if (sprite.data[3] != 0)
          {
              sprite.data[3]--;
          }
          else
          {
              sprite.data[3] = 2;
              if (sprite.data[7] <= COLOR_CHANGES)
              {
                  rt.CpuCopy16((rt.getExtraPalette("&gIntroGameFreakTextFade_Pal[sprite.data[7]]") ?? new Uint16Array(0)), 0, (256 + (1) * 16) + 15, Math.floor((PLTT_SIZEOF(1) / 2)));
                  rt.CpuCopy16((rt.getExtraPalette("&gIntroGameFreakTextFade_Pal[sprite.data[7] + 16]") ?? new Uint16Array(0)), 0, (256 + (1) * 16) + 4, Math.floor((PLTT_SIZEOF(1) / 2)));
                  rt.CpuCopy16((rt.getExtraPalette("&gIntroGameFreakTextFade_Pal[sprite.data[7] + 32]") ?? new Uint16Array(0)), 0, (256 + (1) * 16) + 10, Math.floor((PLTT_SIZEOF(1) / 2)));
                  sprite.data[7]++;
              }
              else
              {
                  sprite.data[0]++;
              }
          }
          break;
      case 4:
          if (rt.gIntroFrameCounter >= TIMER_LOGO_DISAPPEAR)
          {
               
              rt.StartSpriteAffineAnim(sprite.spriteId, 2);
              rt.gba.oam[sprite.oamIndex].objMode = ST_OAM_OBJ_BLEND;
              sprite.data[0]++;
          }
          break;
      case 5:
           
          sprite.data[3] += sGameFreakLettersMoveSpeed[sprite.data[2]];
          sprite.x2 = (sprite.data[3] & 0xFF00) >> 8;
          if (sprite.data[2] < 4)
          {
               
              let temp = sprite.x2;
              sprite.x2 = -temp;
          }
          if (sprite.affineAnimEnded)
              rt.DestroySprite(sprite.spriteId);
          break;
      }
};

/** Source: intro.c → SpriteCB_GameFreakLogo */
export const SpriteCB_GameFreakLogo: SpriteCallback = (sprite, rt) => {
  switch(sprite.data[0])
      {
      case 0:
          if (rt.gIntroFrameCounter >= TIMER_LOGO_APPEAR)
          {
              sprite.invisible = false;
              sprite.data[0]++;
          }
          break;
      case 1:
          if (rt.gIntroFrameCounter >= TIMER_LOGO_DISAPPEAR)
          {
               
              rt.StartSpriteAffineAnim(sprite.spriteId, 3);
              sprite.data[0]++;
          }
          break;
      case 2:
          if (sprite.affineAnimEnded)
              rt.DestroySprite(sprite.spriteId);
          break;
      }
};

/** Source: intro.c → SpriteCB_FlygonSilhouette */
export const SpriteCB_FlygonSilhouette: SpriteCallback = (sprite, rt) => {
  sprite.data[7]++;

      if (sprite.data[0] != 0)
      {
          let sin = 0;
          let cos = 0;

          let a, b, c, d;
           
          sin = gSineTable[sprite.data[2]];
          cos = gSineTable[(sprite.data[2] + 64)];
           
          d = Q_8_8_TO_INT( cos * sprite.data[1]);
          c = Q_8_8_TO_INT(-sin * sprite.data[1]);
          b = Q_8_8_TO_INT( sin * sprite.data[1]);
          a = Q_8_8_TO_INT( cos * sprite.data[1]);

          SetOamMatrix(rt.gba, 1, a, b, c, d);
      }

      switch (sprite.data[0])
      {
      case 0:
      default:
          rt.gba.oam[sprite.oamIndex].affineMode = ST_OAM_AFFINE_DOUBLE;
          rt.gba.oam[sprite.oamIndex].affineParamIndex = 1;
          (() => { const _ctcv = CalcCenterToCornerVec(1, 3, 3); sprite.centerToCornerVecX = _ctcv.centerToCornerVecX; sprite.centerToCornerVecY = _ctcv.centerToCornerVecY; })();
          sprite.invisible = false;
          sprite.data[0] = 1;
          sprite.data[1] = 128;
          sprite.data[2] = 0;
          sprite.data[3] = 0;
          break;
      case 1:
          sprite.x2 = -Sin(sprite.data[3], 140);
          sprite.y2 = -Sin(sprite.data[3], 120);
          sprite.data[1] += 7;
          sprite.data[3] += 3;
          if (sprite.x + sprite.x2 <= -16)
          {
              rt.gba.oam[sprite.oamIndex].priority = 3;
              sprite.data[0]++;
              sprite.x = 20;
              sprite.y = 40;
              sprite.data[1] = 512;
              sprite.data[2] = 0;
              sprite.data[3] = 16;
          }
          break;
      case 2:
          sprite.x2 = Sin(sprite.data[3], 34);
          sprite.y2 = -Cos(sprite.data[3], 60);
          sprite.data[1] += 2;
          if (sprite.data[7] % 5 == 0)
              sprite.data[3]++;
          break;
      }
};

/** Source: intro.c → SpriteCB_RayquazaOrb */
export const SpriteCB_RayquazaOrb: SpriteCallback = (sprite, rt) => {
  let foo = 0;
      switch (sprite.data[0])
      {
      case 0:
      default:
          sprite.invisible = false;
          rt.gba.oam[sprite.oamIndex].affineMode = ST_OAM_AFFINE_DOUBLE;
          rt.gba.oam[sprite.oamIndex].affineParamIndex = 18;
          (() => { const _ctcv = CalcCenterToCornerVec(0, 3, 3); sprite.centerToCornerVecX = _ctcv.centerToCornerVecX; sprite.centerToCornerVecY = _ctcv.centerToCornerVecY; })();
          sprite.data[1] = 0;
          sprite.data[0] = 1;
           
      case 1:
          sprite.data[7]++;
          if (sprite.data[7] & 1)
          {
              sprite.invisible = true;
          }
          else
          {
              sprite.invisible = false;
              if (sprite.data[1] < 64)
                  sprite.data[1]++;
          }
          foo = 256 - gSineTable[sprite.data[1]] / 2;
          SetOamMatrix(rt.gba, 18, foo, 0, 0, foo);
          break;
      }
};

