/** Source: intro.c → Task_Scene2_BikeRide */
export const Task_Scene2_BikeRide: TaskCallback = (task, rt) => {
  const taskId = task.taskId;
  let offset = 0;

      if (rt.gIntroFrameCounter >= TIMER_TORCHIC_EXIT)
      {
           
          gIntroCredits_MovingSceneryState = INTROCRED_SCENERY_FROZEN;
          rt.DestroyTask(task.data[0]);
      }

      if (rt.gIntroFrameCounter > TIMER_END_SCENE_2)
      {
           
          rt.BeginNormalPaletteFade("PALETTES_ALL", 8, 0, 16, "RGB_WHITEALPHA");
          task.func = (t) => Task_Scene2_End(t, rt);
      }

       
       
      if (rt.gIntroFrameCounter >= TIMER_PLAYER_DRIFT_BACK)
          _gs(rt, task.data[1]).data[0] = 1;
      if (rt.gIntroFrameCounter >= TIMER_PLAYER_MOVE_FORWARD)
          _gs(rt, task.data[1]).data[0] = 0;
      if (rt.gIntroFrameCounter >= TIMER_FLYGON_ENTER)
          _gs(rt, task.data[2]).data[0] = 1;
      if (rt.gIntroFrameCounter >= TIMER_PLAYER_MOVE_BACKWARD)
          _gs(rt, task.data[1]).data[0] = 2;
      if (rt.gIntroFrameCounter >= TIMER_PLAYER_HOLD_POSITION)
          _gs(rt, task.data[1]).data[0] = 3;
      if (rt.gIntroFrameCounter >= TIMER_PLAYER_EXIT)
          _gs(rt, task.data[1]).data[0] = 4;

       
      offset = Sin(task.data[3] >> 2 & 0x7, 48);
      sFlygonYOffset = offset;
      if (task.data[3] < 512)
          task.data[3]++;

       
      CycleSceneryPalette(0);
};

