/** Source: intro.c → Task_Scene3_SpinPokeball */
export const Task_Scene3_SpinPokeball: TaskCallback = (task, rt) => {
  const taskId = task.taskId;
  task.data[0] += 0x400;

      if (task.data[1] <= 0x6BF)
      {
          task.data[1] += task.data[2];
          task.data[2] += 2;
      }
      else
      {
          task.func = (t) => Task_Scene3_WaitGroudon(t, rt);
      }

      PanFadeAndZoomScreen(DISPLAY_WIDTH / 2, DISPLAY_HEIGHT / 2, ((task.data[1]) === 0 ? 0 : ((0x10000) / (task.data[1])) | 0), task.data[0]);

      if (rt.gIntroFrameCounter >= TIMER_POKEBALL_FADE)
          rt.BeginNormalPaletteFade("PALETTES_ALL", 0, 0, 16, "RGB_WHITEALPHA");
};

