/** Source: intro.c → Task_Scene3_Groudon */
export const Task_Scene3_Groudon: TaskCallback = (task, rt) => {
  const taskId = task.taskId;
  const data = task.data;

      data[7]++;
      if ((data[0] >= 1 && data[0] <= 7) && data[7] % 2 == 0)
          data[4] ^= 3;
      PanFadeAndZoomScreen(data[1], data[2] + data[4], data[3], 0);
      switch (data[0])
      {
      case 0:
          data[1] += 16;
          if (data[1] == 160)
          {
              data[0]++;
              data[6] = 2;
              data[7] = 0x1E2;
              CreateGroudonRockSprites(taskId);
          }
          break;
      case 1:
          if (--data[6] == 0)
          {
              data[6] = 2;
              rt.CpuCopy16(INTRO3_RAW_PTR(data[7]), 0, ((1) * 16) + 15, Math.floor((PLTT_SIZEOF(1) / 2)));
              data[7] += 2;
              if (data[7] == 0x1EC)
                  data[0]++;
          }
          break;
      case 2:
          if (--data[6] == 0)
          {
              data[6] = 2;
              data[0]++;
          }
          break;
      case 3:
          if (--data[6] == 0)
          {
              data[6] = 2;
              rt.CpuCopy16(INTRO3_RAW_PTR(data[7]), 0, ((1) * 16) + 15, Math.floor((PLTT_SIZEOF(1) / 2)));
              data[7] -= 2;
              if (data[7] == 0x1E0)
              {
                  data[6] = 8;
                  data[0]++;
              }
          }
          break;
      case 4:
          if (--data[6] == 0)
          {
              data[1] = -96;
              data[2] = 169;
              data[6] = 3;
              data[0]++;
          }
          break;
      case 5:
          if (--data[6] == 0)
          {
              data[1] = 80;
              data[2] = 41;
              data[6] = 16;
              PlayCryInternal(SPECIES_GROUDON, 0, 100, CRY_PRIORITY_NORMAL, CRY_MODE_NORMAL);
              data[0]++;
          }
          break;
      case 6:
          if (--data[6] == 0)
          {
              data[1] = 80;
              data[2] = 40;
              data[0]++;
          }
          break;
      case 7:
          data[1] += 4;
          data[2] += 4;
          data[6] += 0x666;
          data[3] = Sin((data[6] & 0xFF00) >> 8, 64) + 256;
          if (data[1] == 120)
          {
              rt.BeginNormalPaletteFade("PALETTES_ALL & ~1", 3, 0, 16, "RGB_WHITE");
              data[3] = 256;
              data[4] = 0;
              data[0]++;
          }
          break;
      case 8:
          if (data[3])
              data[3] -= 8;
          else
              data[0]++;
          break;
      case 9:
          if (!rt.gPaletteFade.active)
          {
              task.func = (t) => Task_Scene3_LoadKyogre(t, rt);
              gScanlineEffect.state = 3;
          }
          break;
      }
};

