/** Source: intro.c → Task_Scene3_Kyogre */
export const Task_Scene3_Kyogre: TaskCallback = (task, rt) => {
  const taskId = task.taskId;
  const data = task.data;

      PanFadeAndZoomScreen(data[1], data[2], data[3], 0);

      switch (data[0])
      {
      case 0:
          if (--data[6] != 0)
              break;
          data[0]++;
      case 1:
          data[6] += 4;
          task.data[1] = 344 - Sin(data[6], 0x100);
          task.data[2] = 84 - Cos(data[6], 0x40);
          if (data[6] == 64)
          {
              data[6] = 0x19;
              data[7] = 1;
              data[0]++;
              CreateKyogreBubbleSprites_Body(0);
          }
          break;
      case 2:
          if (--data[6] == 0)
          {
              task.data[1] += 256;
              task.data[2] -= 258;
              data[6] = 8;
              data[0]++;
              CreateKyogreBubbleSprites_Body(0);
              CreateKyogreBubbleSprites_Fins();
          }
          break;
      case 3:
          if (--data[6] == 0)
          {
              task.data[1] -= 256;
              task.data[2] += 258;
              data[6] = 8;
              data[0]++;
          }
          break;
      case 4:
          if (--data[6] == 0)
          {
              task.data[2] -= 252;
              data[6] = 8;
              data[0]++;
          }
          break;
      case 5:
          if (--data[6] == 0)
          {
              task.data[2] += 252;
              if (data[7] != 0)
              {
                  data[6] = 12;
                  data[7]--;
                  data[0] = 2;
              }
              else
              {
                  data[6] = 1;
                  data[0]++;
                  PlayCryInternal(SPECIES_KYOGRE, 0, 120, CRY_PRIORITY_NORMAL, CRY_MODE_NORMAL);
              }
          }
          break;
      case 6:
          if (--data[6] == 0)
          {
              data[6] = 4;
              data[7] = 0x1EA;
              data[0]++;
          }
          break;
      case 7:
          if (--data[6] == 0)
          {
              data[6] = 4;
              rt.CpuCopy16(INTRO3_RAW_PTR(data[7]), 0, ((2) * 16) + 15, Math.floor((PLTT_SIZEOF(1) / 2)));
              data[7] -= 2;
              if (data[7] == 0x1E0)
                  data[0]++;
          }
          break;
      case 8:
          if (--data[6] == 0)
          {
              data[6] = 4;
              data[7] = 0x1E2;
              data[0]++;
          }
          break;
      case 9:
          if (--data[6] == 0)
          {
              data[6] = 4;
              rt.CpuCopy16(INTRO3_RAW_PTR(data[7]), 0, ((2) * 16) + 15, Math.floor((PLTT_SIZEOF(1) / 2)));
              data[7] += 2;
              if (data[7] == 0x1EE)
              {
                  data[6] = 16;
                  data[0]++;
              }
          }
          break;
      case 10:
          if (--data[6] == 0)
          {
              data[6] = 0;
              data[0]++;
              CreateKyogreBubbleSprites_Body(taskId);
          }
          break;
      case 11:
          data[6] += 4;
          data[3] -= 8;
          task.data[1] = Sin(data[6], 0x3C) + 88;
          if (data[6] == 64)
          {
              rt.BeginNormalPaletteFade("PALETTES_ALL & ~1", 3, 0, 16, "RGB_WHITE");
              data[0]++;
          }
          break;
      case 12:
          data[6] += 4;
          data[3] -= 8;
          task.data[1] = Sin(data[6], 0x14) + 128;
          if (data[6] == 128)
              data[0]++;
          break;
      case 13:
          if (!rt.gPaletteFade.active)
          {
              task.func = (t) => Task_Scene3_LoadClouds1(t, rt);
              gScanlineEffect.state = 3;
          }
          break;
      }
};

