/** Source: intro.c → Task_Scene3_Clouds */
export const Task_Scene3_Clouds: TaskCallback = (task, rt) => {
  const taskId = task.taskId;
  const data = task.data;

       
      rt.SetGpuReg(REG_OFFSET_BG0HOFS, (data[6] >> 8));
      rt.SetGpuReg(REG_OFFSET_BG1HOFS, -(data[6] >> 8));

      switch (data[0])
      {
      case 0:
           
           
          if (--data[6] == 0)
          {
               
              rt.BeginNormalPaletteFade("PALETTES_ALL & ~1", 0, 16, 0, "RGB_WHITEALPHA");
              data[6] = 80 << 8;
              data[0]++;
          }
          break;
      case 1:
           
          if (data[6] == 40 << 8)
              rt.BeginNormalPaletteFade("PALETTES_BG & ~1", 3, 0, 16, "RGB(9, 10, 10)");

           
          if (data[6] != 0)
              data[6] -= 128;
          else if (!rt.gPaletteFade.active)
              task.func = (t) => Task_Scene3_LoadLightning(t, rt);
          break;
      }
};

/** Source: intro.c → Task_Scene3_LoadLightning */
export const Task_Scene3_LoadLightning: TaskCallback = (task, rt) => {
  const taskId = task.taskId;
  LZDecompressVram(gIntroRayquaza_Tilemap, (BG_SCREEN_ADDR(28)));
      LZDecompressVram(gIntroRayquazaClouds_Tilemap, (BG_CHAR_ADDR(3)));
      LZDecompressVram(gIntroRayquaza_Gfx, (BG_CHAR_ADDR(1)));
      LZDecompressVram(gIntroRayquazaClouds_Gfx, VRAM);
      rt.SetGpuReg(REG_OFFSET_DISPCNT, DISPCNT_MODE_0
                                  | DISPCNT_OBJ_1D_MAP
                                  | DISPCNT_BG0_ON
                                  | DISPCNT_BG2_ON
                                  | DISPCNT_OBJ_ON
                                  | DISPCNT_WIN0_ON);
      task.func = (t) => Task_Scene3_Lightning(t, rt);
      task.data[0] = 0;
      task.data[6] = 1;
      task.data[7] = 0;
      LoadCompressedSpriteSheetUsingHeap(sSpriteSheet_Lightning);
      /* TODO LoadSpritePalettes — load via rt.LoadSpritePalettesFromTable */;
};

/** Source: intro.c → Task_Scene3_Lightning */
export const Task_Scene3_Lightning: TaskCallback = (task, rt) => {
  const taskId = task.taskId;
  const data = task.data;
      let spriteId = 0;

      switch (data[0])
      {
      case 0:
          if (--data[6] == 0)
          {
               
              rt.CreateSpriteFromTemplate('sSpriteTemplate_Lightning',  200, 48, 0);
              spriteId = rt.CreateSpriteFromTemplate('sSpriteTemplate_Lightning',  200, 80, 1);
              rt.StartSpriteAnim(spriteId, 1);
              spriteId = rt.CreateSpriteFromTemplate('sSpriteTemplate_Lightning',  200, 112, 2);
              rt.StartSpriteAnim(spriteId, 2);
              data[0]++;
              data[6] = 72;
          }
          break;
      case 1:
          if (--data[6] == 0)
          {
               
              rt.CreateSpriteFromTemplate('sSpriteTemplate_Lightning',  40, 48, 0);
              spriteId = rt.CreateSpriteFromTemplate('sSpriteTemplate_Lightning',  40, 80, 1);
              rt.StartSpriteAnim(spriteId, 1);
              spriteId = rt.CreateSpriteFromTemplate('sSpriteTemplate_Lightning',  40, 112, 2);
              rt.StartSpriteAnim(spriteId, 2);
              data[0]++;
              data[6] = 48;
          }
          break;
      case 2:
          if (--data[6] == 0)
              task.func = (t) => Task_Scene3_LoadRayquazaAttack(t, rt);
          break;
      }
};

/** Source: intro.c → Task_Scene3_LoadRayquazaAttack */
export const Task_Scene3_LoadRayquazaAttack: TaskCallback = (task, rt) => {
  const taskId = task.taskId;
  let attackTaskId = 0;

      /* TODO LoadCompressedSpriteSheet — load via rt.LoadCompressedSpriteSheetsFromTable */;
      /* TODO LoadSpritePalettes — load via rt.LoadSpritePalettesFromTable */;
      rt.SetGpuReg(REG_OFFSET_DISPCNT, DISPCNT_MODE_0
                                  | DISPCNT_OBJ_1D_MAP
                                  | DISPCNT_BG0_ON
                                  | DISPCNT_BG2_ON
                                  | DISPCNT_OBJ_ON
                                  | DISPCNT_WIN0_ON);
      task.func = (t) => Task_Scene3_Rayquaza(t, rt);
      rt.BeginNormalPaletteFade("PALETTES_BG & ~(0x21)", 0, 16, 0, "RGB(9, 10, 10)");
      task.data[0] = 0;
      task.data[1] = 0xA8;
      task.data[2] = -0x10;
      task.data[3] = -0x88;
      task.data[4] = -0x10;
      attackTaskId = rt.CreateTask((t) => Task_RayquazaAttack(t, rt), 0);
      _gt(rt, attackTaskId).data[4] = taskId;
};

/** Source: intro.c → Task_Scene3_Rayquaza */
export const Task_Scene3_Rayquaza: TaskCallback = (task, rt) => {
  const taskId = task.taskId;
  const data = task.data;

      if (data[7] % 2 == 0)
          data[6] ^= 2;

      data[7]++;

      switch(data[0])
      {
      case 0:
          if ((data[7] & 1) != 0)
          {
              data[1] -= 2;
              data[2]++;
              data[3] += 2;
              data[4]++;
          }
          if (data[1] == 0x68)
          {
              data[0]++;
              data[5] = 1;
          }
          break;
      case 1:
          data[0]++;
          data[5] = 4;
          break;
      case 2:
          data[1] += 4;
          data[2] -= 2;
          data[3] -= 4;
          data[4] -= 2;
          if (!rt.gPaletteFade.active)
          {
              data[5] = 0x8C;
              data[0]++;
          }
          break;
      case 3:
          if (--data[5] == 0)
              task.func = (t) => Task_EndIntroMovie(t, rt);
          break;
      }
};

