/** Source: intro.c → Task_RayquazaAttack */
export const Task_RayquazaAttack: TaskCallback = (task, rt) => {
  const taskId = task.taskId;
  let spriteId = 0;
      const data = task.data;
      data[2]++;

      switch(data[0])
      {
      case 0:
          if ((data[2] & 1) != 0)
          {
              rt.CpuCopy16(INTRO3_RAW_PTR(0x1A2 + data[1] * 2), 0, ((5) * 16) + 14, Math.floor((PLTT_SIZEOF(1) / 2)));
              data[1]++;
          }
          if (data[1] == 6)
          {
              data[0]++;
              data[1] = 0;
              data[3] = 10;
          }
          break;
      case 1:
          if (data[3] == 0)
          {
              if ((data[2] & 1) != 0)
              {
                  rt.CpuCopy16(INTRO3_RAW_PTR(0x1A2 + data[1] * 2), 0, ((5) * 16) + 8, Math.floor((PLTT_SIZEOF(1) / 2)));
                  data[1]++;
              }
              if (data[1] == 6)
              {
                  data[0]++;
                  data[3] = 10;
              }
          }
          else
          {
              data[3]--;
          }
          break;
      case 2:
          if (data[3] == 0)
          {
              if ((data[2] & 1) != 0)
              {
                  rt.CpuCopy16(INTRO3_RAW_PTR(0x182 + data[1] * 2), 0, ((5) * 16) + 12, Math.floor((PLTT_SIZEOF(1) / 2)));
                  data[1]++;
              }
              if (data[1] == 6)
              {
                  spriteId = rt.CreateSpriteFromTemplate('sSpriteTemplate_RayquazaOrb',  120, 88, 15);
                  /* TODO sound PlaySE */;
                  _gs(rt, spriteId).invisible = true;
                  _gs(rt, spriteId).data[3] = data[4];
                  data[0]++;
                  data[3] = 16;
              }
          }
          else
          {
              data[3]--;
          }
          break;
      case 3:
          if ((data[2] & 1) != 0)
          {
              if (--data[3] != 0)
              {
                  BlendPalette(BG_PLTT_ID(5), 16, data[3], RGB(9, 10, 10));
                  rt.CpuCopy16(INTRO3_RAW_PTR(428), 0, ((5) * 16) + 14, Math.floor((PLTT_SIZEOF(1) / 2)));
                  rt.CpuCopy16(INTRO3_RAW_PTR(428), 0, ((5) * 16) + 8, Math.floor((PLTT_SIZEOF(1) / 2)));
                  rt.CpuCopy16(INTRO3_RAW_PTR(396), 0, ((5) * 16) + 12, Math.floor((PLTT_SIZEOF(1) / 2)));
              }
              else
              {
                  data[0]++;
                  data[3] = 53;
              }
          }
          break;
      case 4:
          if (--data[3] == 0)
          {
              rt.BeginNormalPaletteFade("PALETTES_ALL", 0, 0, 16, "RGB_WHITE");
              data[0]++;
          }
          break;
      case 5:
          if (!rt.gPaletteFade.active)
              rt.DestroyTask(taskId);
          break;
      }
};

/** Source: intro.c → Task_BlendLogoIn */
export const Task_BlendLogoIn: TaskCallback = (task, rt) => {
  const taskId = task.taskId;
  switch (task.data[0])
      {
      case 0:
      default:
          rt.SetGpuReg(REG_OFFSET_BLDCNT, BLDCNT_EFFECT_BLEND
                                     | BLDCNT_TGT2_BG0
                                     | BLDCNT_TGT2_BG1
                                     | BLDCNT_TGT2_BG2
                                     | BLDCNT_TGT2_BG3
                                     | BLDCNT_TGT2_OBJ
                                     | BLDCNT_TGT2_BD);
          rt.SetGpuReg(REG_OFFSET_BLDALPHA, gTitleScreenAlphaBlend[31]);
          rt.SetGpuReg(REG_OFFSET_BLDY, 0);
          task.data[1] = ((gTitleScreenAlphaBlend)?.length ?? 0);
          task.data[0]++;
          break;
      case 1:
          if (task.data[1] != 0)
          {
              let tmp = 0;

              task.data[1]--;
              tmp = task.data[1] / 2;
              rt.SetGpuReg(REG_OFFSET_BLDALPHA, gTitleScreenAlphaBlend[tmp]);
          }
          else
          {
              rt.SetGpuReg(REG_OFFSET_BLDALPHA, gTitleScreenAlphaBlend[0]);
              task.data[1] = ((gTitleScreenAlphaBlend)?.length ?? 0) / 4;
              task.data[0]++;
          }
          break;
      case 2:
          rt.SetGpuReg(REG_OFFSET_BLDCNT, 0);
          rt.SetGpuReg(REG_OFFSET_BLDALPHA, 0);
          rt.SetGpuReg(REG_OFFSET_BLDY, 0);
          rt.DestroyTask(taskId);
          break;
      }
};

/** Source: intro.c → Task_BlendLogoOut */
export const Task_BlendLogoOut: TaskCallback = (task, rt) => {
  const taskId = task.taskId;
  switch (task.data[0])
      {
      case 0:
      default:
          rt.SetGpuReg(REG_OFFSET_BLDCNT, BLDCNT_EFFECT_BLEND
                                     | BLDCNT_TGT2_BG0
                                     | BLDCNT_TGT2_BG1
                                     | BLDCNT_TGT2_BG2
                                     | BLDCNT_TGT2_BG3
                                     | BLDCNT_TGT2_OBJ
                                     | BLDCNT_TGT2_BD);
          rt.SetGpuReg(REG_OFFSET_BLDALPHA, gTitleScreenAlphaBlend[0]);
          rt.SetGpuReg(REG_OFFSET_BLDY, 0);
          task.data[1] = 0;
          task.data[0]++;
          break;
      case 1:
          if (task.data[1] < ((gTitleScreenAlphaBlend)?.length ?? 0) - 2)
          {
              let tmp = 0;

              task.data[1]++;
              tmp = task.data[1] / 2;
              rt.SetGpuReg(REG_OFFSET_BLDALPHA, gTitleScreenAlphaBlend[tmp]);
          }
          else
          {
              rt.SetGpuReg(REG_OFFSET_BLDALPHA, gTitleScreenAlphaBlend[31]);
              task.data[1] = ((gTitleScreenAlphaBlend)?.length ?? 0) / 4;
              task.data[0]++;
          }
          break;
      case 2:
          if (task.data[1] != 0)
          {
              task.data[1]--;
          }
          else
          {
              rt.SetGpuReg(REG_OFFSET_BLDCNT, 0);
              rt.SetGpuReg(REG_OFFSET_BLDALPHA, 0);
              rt.SetGpuReg(REG_OFFSET_BLDY, 0);
              rt.DestroyTask(taskId);
          }
          break;
      }
};

