/** Source: intro.c → CreateWaterDrop (helper) */
export function CreateWaterDrop(x: number, y: number, c: number, d: number, e: number, fallImmediately: number): number {
  const rt = _getRuntime();
  let sprite: any = _emptySprite;
  let task: any = _emptyTask;
  let spriteId = 0;
      let oldSpriteId = 0;

       
      spriteId = rt.CreateSpriteFromTemplate('sSpriteTemplate_WaterDrop',  x, y, 1);
      _gs(rt, spriteId).data[0] = 0;
      _gs(rt, spriteId).data[7] = 0;
      _gs(rt, spriteId).data[1] = d;
      _gs(rt, spriteId).data[2] = c;
      _gs(rt, spriteId).data[3] = c;
      _gs(rt, spriteId).data[5] = e;
      _gs(rt, spriteId).data[6] = c;
      rt.gba.oam[_gs(rt, spriteId).oamIndex].affineMode = ST_OAM_AFFINE_DOUBLE;
      rt.gba.oam[_gs(rt, spriteId).oamIndex].affineParamIndex = d;
      CalcCenterToCornerVec(_gs(rt, spriteId), 0, 2, ST_OAM_AFFINE_ERASE);
      rt.StartSpriteAnim(spriteId, DROP_ANIM_REFLECTION);
      if (!fallImmediately)
          rt.setSpriteCallback(spriteId, SpriteCB_WaterDrop);  
      else
          rt.setSpriteCallback(spriteId, SpriteCB_WaterDropShort);  
      oldSpriteId = spriteId;

       
       
      spriteId = rt.CreateSpriteFromTemplate('sSpriteTemplate_WaterDrop',  x, y, 1);
      _gs(rt, spriteId).data[7] = oldSpriteId;
      _gs(rt, spriteId).data[1] = d + 1;
      rt.gba.oam[_gs(rt, spriteId).oamIndex].affineMode = ST_OAM_AFFINE_DOUBLE;
      rt.gba.oam[_gs(rt, spriteId).oamIndex].affineParamIndex = d + 1;
      CalcCenterToCornerVec(_gs(rt, spriteId), 0, 2, ST_OAM_AFFINE_ERASE);
      rt.setSpriteCallback(spriteId, SpriteCB_WaterDropHalf);

       
      spriteId = rt.CreateSpriteFromTemplate('sSpriteTemplate_WaterDrop',  x, y, 1);
      _gs(rt, spriteId).data[7] = oldSpriteId;
      _gs(rt, spriteId).data[1] = d + 2;
      rt.StartSpriteAnim(spriteId, DROP_ANIM_LOWER_HALF);
      rt.gba.oam[_gs(rt, spriteId).oamIndex].affineMode = ST_OAM_AFFINE_DOUBLE;
      rt.gba.oam[_gs(rt, spriteId).oamIndex].affineParamIndex = d + 2;
      CalcCenterToCornerVec(_gs(rt, spriteId), 0, 2, ST_OAM_AFFINE_ERASE);
      rt.setSpriteCallback(spriteId, SpriteCB_WaterDropHalf);

      SetOamMatrix(rt.gba, d, c + 32, 0, 0, c + 32);
      SetOamMatrix(rt.gba, d + 1, c + 32, 0, 0, c + 32);
      SetOamMatrix(rt.gba, d + 2, c + 32, 0, 0, 2 * (c + 32));

      return oldSpriteId;
  return -1;
}

